import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.SpawnExperienceOrb{Position: mgl32.Vec3{1, 2, 3}, ExperienceAmount: 300}
GOLDEN = bytes.fromhex("0000803f0000004000004040d804")

# generated by gophertunnel b8bd735:
# packet.SpawnExperienceOrb{ExperienceAmount: -1}
NEGATIVE_XP = bytes.fromhex("00000000000000000000000001")

GOLDENS = [
    pytest.param(
        v2225.SpawnExperienceOrbPacket(pos=v2225.Vec3(x=1.0, y=2.0, z=3.0), xp_value=300),
        GOLDEN,
        id="positive-xp",
    ),
    pytest.param(v2225.SpawnExperienceOrbPacket(xp_value=-1), NEGATIVE_XP, id="negative-xp"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_spawn_experience_orb_is_packet_66(version):
    assert version.PACKETS[66] is version.SpawnExperienceOrbPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_spawn_experience_orb_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_spawn_experience_orb_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
